// TH16 v1.00a Extra — Boss7 (7th nonspell), st07bs.ecl.txt:681-741.
// Entry interrupt: setInterrupt(0, 3000, 4200, "BossCard7") — 4200-frame window
// from timerReset; HP interrupt is not modelled (invulnerable training shell).

// Approved TH16 type alias (0..43 reuse of the verified TH18 slots).
const TH16_SHARD: int = 512;

const TIME_LIMIT: int = 4324;      // 120 shell buffer + 4200 source window + 4 startup margin
const OPENING_BUFFER: int = 120;
const SOURCE_WINDOW: int = 4200;
const INTRO: int = 180;            // wait(120) + wait(60) before Boss7_1192
const LOOP_FRAMES: int = SOURCE_WINDOW - INTRO;

const MOVE_START_SPEED: fx = 1.9fx;   // moveRand(60, 4, 1.9)
const MOVE_FRAMES: int = 60;
const LIMIT_X: fx = 120fx;            // moveLimit(0,128,240,64): x in [-120,120]
const LIMIT_Y_TOP: fx = 96fx;         // y in [96,160]
const LIMIT_Y_BOTTOM: fx = 160fx;
const RAND_X_INNER: fx = 60fx;        // inner zone = center +- width/4
const RAND_Y_TOP: fx = 112fx;         // center +- height/4
const RAND_Y_BOTTOM: fx = 144fx;

// ---------------------------------------------------------------- shell

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // Independent card starts the boss at its own settle point (0,128).
    _ = spawn_enemy(0fx, 128fx, 14000, 0, 0, 0, source_enemy);
}

// ---------------------------------------------------------------- Boss7

async sub source_enemy() {
    // Restored entry state: Boss() setHurtbox(40,40)/setHitbox(48,48) -> circular radius *0.5.
    set_invuln(65535);
    set_hurtbox(20fx);
    set_hitbox(24fx);
    // moveVel(0,0) / moveVelTime(0,0,0,0) / movePosTime(0,0,0,0): clear motion only.
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    // movePosTime(60, 4, 0.0f, 128.0f); zero displacement from the chosen entry point.
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(120);
    // moveLimit(0.0f, 128.0f, 240.0f, 64.0f) is enforced by arm_next_step().
    wait(60);
    // Boss7_1192 / Boss7_1424: alternating +-8deg ring calls with a 1.9-speed random drift.
    // Each half-cycle is wait(100) + the 60-frame moveRand; 25 half-cycles fit the window.
    for cycle in 0..12 {
        spawn volley(aim_player(), 8deg, 91);
        wait(100);
        move_rand();
        move_rand_wait(60);
        spawn volley(aim_player(), -8deg, -91);
        wait(100);
        move_rand();
        move_rand_wait(60);
    }
    spawn volley(aim_player(), 8deg, 91);
    wait(100);
    move_rand();
    move_rand_wait(60);
    // Source window ends 20 frames into the 26th half-cycle (interrupt at 4200).
    spawn volley(aim_player(), -8deg, -91);
    wait(LOOP_FRAMES - 25 * 160);
}

// ---------------------------------------------------------------- Boss7_at

// etNew/etAim(3)/etSprite(10,2)/etCount(3,5)/etAngle/etSpeed(4.5,3.0)/etDist(32)/
// etOffset(0,-24); 60 volleys, 3 frames apart. %C starts at ANGLE_PLAYER and steps by A;
// B is the role of the second etAngle argument (layer deflection).
async sub volley(start_angle: angle, step: angle, layer_step: int) {
    sh_reset(0);
    sh_sprite(0, TH16_SHARD, 2);
    sh_ring(0, 1);                 // etAim mode 3: fixed-direction ring
    sh_aim(0, 0);
    sh_offset(0, 0fx, -24fx);      // etOffset(0, 0.0f, -24.0f)
    sh_count(0, 3, 1);             // etCount(0, 3, 5); layers fired below for per-layer etDist
    var base: angle = start_angle;
    for k in 0..60 {
        for q in 0..5 {
            // etSpeed(0, 4.5f, 3.0f): v(q) = s0 + (s1-s0)*q/(M-1)
            var v: fx = 4.5fx - q as fx * 0.375fx;
            sh_angle(0, base + (q * layer_step) as angle, 0deg);
            sh_speed(0, v, 0fx);
            // etDist(32) plus the ANIM birth retreat position -= 4*velocity.
            sh_dist(0, 32fx - 4fx * v);
            sh_fire(0);
        }
        base = base + step;
        wait(3);
    }
}

// ---------------------------------------------------------------- movement

// moveRand(60, 4, 1.9): one signed direction sample per call, then 60 linear
// deceleration steps. Speed inherits mode0 (the mode argument does not cover it).
sub move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -RAND_X_INNER {
        a = r / 3;
    } else if $self_x > RAND_X_INNER {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < RAND_Y_TOP {
        if a < 0 { a = -a; }
    } else if $self_y > RAND_Y_BOTTOM {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard, epsilon 0.05 rad (~522 BAM).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    arm_next_step();
}

// Arm the next source movement tick; phase 5 integrates it after this frame's ECL.
sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < MOVE_FRAMES {
        speed = ((MOVE_FRAMES - k) as fx / MOVE_FRAMES) * MOVE_START_SPEED;
    }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -LIMIT_X { nx = -LIMIT_X; }
    if nx > LIMIT_X { nx = LIMIT_X; }
    if ny < LIMIT_Y_TOP { ny = LIMIT_Y_TOP; }
    if ny > LIMIT_Y_BOTTOM { ny = LIMIT_Y_BOTTOM; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub move_rand_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}
